"""Write the delivered bound, exact comparisons and warm-search evidence."""
import csv,gzip,hashlib,json,re,time
from fractions import Fraction
from pathlib import Path
from checkpoint import decimal_out
from numerics import register
register('finish_report')

def read(p):
    p=Path(p)
    if not p.exists():p=Path(str(p)+'.gz')
    return json.loads(gzip.decompress(p.read_bytes()) if p.suffix=='.gz' else p.read_bytes())
r=read('RESULT.json');cert=read('certificate.json');v=read('evidence/final-replay.json');prov=read('FACTOR_PROVENANCE.json')
master=read('prior_sources/round8-master.json')
for kind in ['denominator','numerator']:
    for row in prov[kind]:
        extra=[{'origin':'round-8 final LP master','name':other['name']} for other in master[kind] if row['coeffs']==other['coeffs']]
        row['all_full_coefficient_matches']=[m for m in row['all_full_coefficient_matches'] if m['origin']!='round-8 final LP master']+extra
        if extra and row['origin']=='new here':row['origin']=extra[0]['origin']
Path('FACTOR_PROVENANCE.json').write_text(json.dumps(prov,indent=2)+'\n')
finished=read('rounds/finished.json');start=read('evidence/start.json')['start_epoch'];hi=Fraction(r['exact_upper']);lo=Fraction(r['exact_lower'])
assert hi<Fraction(r['stated_rational'])
assert hashlib.sha256(Path('certificate.json').read_bytes()).hexdigest()==r['certificate_sha256']==v['certificate_sha256']
controls=read('evidence/rejection-controls.json');assert all(x['rejected'] for x in controls)
records=[json.loads(x) for x in Path('evidence/compute.jsonl').read_text().splitlines()]
cpu=sum(x['cpu_seconds'] for x in records);wall=(time.time()-start)/3600;allowance=.01+.01*wall
peaks=[]
for p in Path('.').rglob('*.time'):
    m=re.search(r'(\d+)\s+maximum resident set size',p.read_text())
    if m:peaks.append({'file':str(p),'peak_rss_bytes':int(m.group(1))})
compute={'recorded_cpu_seconds':cpu,'recorded_core_hours':cpu/3600,'estimated_total_core_hours':cpu/3600+allowance,'unmeasured_allowance_core_hours':allowance,'wall_hours':wall,'largest_sampled_aggregate_rss_bytes':max(x.get('sampled_aggregate_peak_bytes',0) for x in records),'worker_peaks':peaks,'accounting':'Sum of disjoint run/batch RUSAGE_CHILDREN deltas, including ps sampling. Estimate adds .01 core-hour setup plus .01 per elapsed hour for controller/setup/reporting.','single_threaded_blas_highs_flint':True,'maximum_simultaneous_numerical_workers':4,'allocation':'4 numerator generation and full-bank pricing, 2 denominator; alternating batches; measured solo generation first round; sequential LP and verifier','nice_command':'nice -n 10'}
Path('COMPUTE.json').write_text(json.dumps(compute,indent=2)+'\n')
summary=[]
for p in sorted([*Path('rounds').glob('*search-*.json'),*Path('rounds').glob('*search-*.json.gz')]):
    d=read(p);summary.append({'file':str(p),'settings':d.get('settings'),'elapsed':d.get('elapsed'),'cpu_seconds':d.get('cpu_seconds'),'trials':d.get('trials'),'priced':d.get('priced'),'negative_candidates':len(d.get('negative_candidates',[])),'best_rc':d['best']['rc'] if d.get('best') else None})
Path('SEARCH_SUMMARY.json').write_text(json.dumps({'searches':summary,'rounds':finished},indent=2)+'\n')
curve=[json.loads(x) for x in Path('evidence/improvement-curve.jsonl').read_text().splitlines()]
with open('IMPROVEMENT_CURVE.csv','w') as out:
    w=csv.writer(out);w.writerow(['elapsed_hours','certified_upper','certificate','replay_source'])
    for row in curve:w.writerow([f"{(row['epoch']-start)/3600:.6f}",row['upper'],row['certificate'],row['replay_source']])
lines=[f"Shipped: candidate, unrefereed C82 < {r['stated_decimal']}; "+('the exact certified upper endpoint is below the frozen 0.2519758216 bar.' if hi<Fraction('0.2519758216') else 'the frozen bar was not reached; this is the best certified value.'),'',f"Certified enclosure: [{r['interval_lower']}, {r['interval_upper']}]. Exact endpoint fraction: {r['exact_upper']}. The endpoint is strictly below the stated rational {r['stated_rational']}; the comparison uses Fraction, without decimal rounding.",'','| Comparator | Certified improvement (at least) |','| --- | ---: |']
for label,q in [('Round 8 printed 0.2519758217','0.2519758217'),('[#330](https://github.com/teorth/optimizationproblems/pull/330) live printed 0.2519923410','0.2519923410'),('[#280 v5](https://github.com/teorth/optimizationproblems/pull/280) printed 0.2519889614','0.2519889614'),('Round 8 upper endpoint 0.2519758216376568674750','0.2519758216376568674750')]:lines.append(f'| {label} | {decimal_out(Fraction(q)-hi,False)} |')
lines += ['',f"The packet has {len(cert['denominator'])} denominators and {len(cert['numerator'])} numerators. D={v['audit']['D']}; deg A={v['audit']['degree_A']}; {v['audit']['coprimality_pairs']} exact gcd pairs and {v['audit']['composed_roots']} composed roots. SHA256: {r['certificate_sha256']}.",'','Verification uses the separately written (same agent) inherited stdlib + python-flint verifier. It checks the hash, integer coefficients, monic denominators, positive integer multiplicities, nonnegative rational powers, strict degree inequality, every active numerator/denominator gcd, exact composition, composed-root isolation and interval integration. Changed bytes, repinned zero multiplicity and repinned shared factor all fail (evidence/rejection-controls.json). The Doche reduction and arithmetic backend are not formally verified. PROOF.md and NUMERICS.md give the inherited mathematical argument and enclosure formulas. All conclusions remain candidate and unrefereed.','', 'Our own round-8 joint LP, numerical helpers, iterated dual-weighted evaluation-lattice LLL numerator pricing, degree-104 monic CVP denominator generation, mergers, controller, checkpoint code, verifier and rejection controls were copied and reused. The search began from its final floating master and dual, without a cold restart: 115 denominators and 37 active numerators, plus its complete bank of 14,192 numerator factors and 109 archive denominators. Its certificate replay reproduced B in [0.2519758216376568634394, 0.2519758216376568674750]. BAR.json was written before search.','', 'The standard alternation was retained: numerator search on the current dual, joint LP and certification, full-bank numerator repricing after each moved solve, then CVP denominator search on the new dual, joint LP and certification. Numerator generation and full-bank pricing receive four workers and CVP two, with sequential solving/verification, following round 8’s frequent numerator gains and occasional larger denominator gains. Initial generation batches ran solo under /usr/bin/time -l before scaling. Full-bank pricing began with the inherited serial implementation; from round 23 its independent per-factor calculations use four workers, with unchanged formulas, complete-bank coverage and ordering. The first full parallel pass completed in 104.9 wall seconds with 559 MB sampled aggregate RSS. Each worker uses one BLAS/HiGHS/FLINT thread and nice -n 10. Search settings, seeds and outcomes are in SEARCH_SUMMARY.json. No pricing or CVP optimality claim is made.','',f"Stopping reason: {finished['stop']}. Completed {len(finished['history'])} alternating rounds (numbered from 22). Three no-gain rounds means three complete rounds without a smaller certified endpoint; the old 1e-10 LP cutoff was larger than this job’s frozen-bar margin. The search time limit leaves time for the final packet within ten hours. No stop is interpreted as an optimality result."]
recent=finished['history'][-3:];worth=any(Fraction(row.get('certified_gain','0'))>0 for row in recent)
lines += ['',('Another warm round is worth trying: the latest completed rounds still improved the certified value and the time budget ended the run.' if worth and 'no-gain' not in finished['stop'] else 'Another identical round is not recommended after three complete rounds without certified gain; a longer or different start budget could still find factors.'),'Resume from '+finished['state']+' and '+finished['dual']+' with the complete bank.','', 'The plot shows all certified checkpoints without fitting or extrapolation. The table lists the baseline, the first improvement in each elapsed hour and the final value; IMPROVEMENT_CURVE.csv records every certified improvement and certificate path.', '', '![Certified improvement curve](IMPROVEMENT_CURVE.png)', '', 'The plot is also available as IMPROVEMENT_CURVE.pdf.','', '| Elapsed hours | Certified upper endpoint |','| ---: | ---: |']
selected=[];seen=set()
for i,row in enumerate(curve):
    hour=int((row['epoch']-start)/3600)
    if hour not in seen or i==len(curve)-1:selected.append(row);seen.add(hour)
for row in selected:lines.append(f"| {(row['epoch']-start)/3600:.3f} | {row['upper']} |")
lines += ['',f"Compute: {cpu/3600:.4f} recorded core-hours; {compute['estimated_total_core_hours']:.4f} estimated total with explicit controller/setup allowance. Wall time {wall:.3f} hours. Largest sampled aggregate RSS {compute['largest_sampled_aggregate_rss_bytes']:,} bytes; 3 GB cap. COMPUTE.json records accounting and measured process peaks. evidence/process-cleanup.json records the final ps check.",'','Factor provenance is by full coefficient comparison, including exact weights and all matches in FACTOR_PROVENANCE.json. A factor absent from the compared sources is labeled “generated in this continuation”; this is provenance only. Names are labels.','', '| Denominator | Degree | Multiplicity | Full coefficient matches |','| --- | ---: | ---: | --- |']
def origins(row):return '; '.join(dict.fromkeys(x['origin'] for x in row['all_full_coefficient_matches'])) or 'generated in this continuation'
for row in prov['denominator']:lines.append(f"| {row['name']} | {len(row['coeffs'])-1} | {row['multiplicity']} | {origins(row)} |")
lines += ['', '| Numerator | Degree | Full coefficient matches |','| --- | ---: | --- |']
for row in prov['numerator']:lines.append(f"| {row['name']} | {len(row['coeffs'])-1} | {origins(row)} |")
lines += ['', 'For every q_rational with a reduced 15- or 16-digit numerator, the equal fraction with numerator and denominator doubled is retained. CERTIFICATE_ENCODING.md and the inherited encoding note identify these entries; exact Fraction arithmetic is unchanged.','', 'No vidigoat Python was downloaded, copied, imported or executed. PYTHON_BLOBS.json records the git blob hash of every .py in this job directory and checks against every blob in complete metadata-only trees at 197962c, 3a7a84f, 79ce0df and 191064e. No matches or imports of their modules were found. Only their already supplied certificate JSON data and tree metadata were used. Credits: Doche, Grinsztajn and Epi, Pinho PR301/#330, Patankar PR280 v3/v4/v5. THIRD_PARTY_NOTICE.md records the inherited factor/method credits.','', 'PRIOR_ART.md records the current public table/open PRs, recent repository searches, lab/result READMEs, papers and community searches, with initial and final read snapshots. Public comparison sources: [#330](https://github.com/teorth/optimizationproblems/pull/330), [#280](https://github.com/teorth/optimizationproblems/pull/280), [official table](https://teorth.github.io/optimizationproblems/constants/82a.html). No novelty judgment is made. All network use was read-only; no commits, pushes, PRs, uploads, posts or messages were made. All retained outputs are in this job directory. Completed history was gzip-compressed; redundant old floating LP/dual caches and compressed originals were moved to macOS Trash to keep the packet below 50 MB. Every certified best and its exact replay remain retained.','', 'Reproduce the bound:','','```sh',f"./run_local.sh verify_best.py --certificate certificate.json --target {r['stated_decimal']} --precision 256 --tol 1e-13 --out evidence/reproduced-best.json",'```','','REPRODUCE.md gives warm search, rejection-control and source-inventory commands. Every new certified best is retained in certificates/.']
Path('REPORT.md').write_text('\n'.join(lines)+'\n')
with open('STATUS.md','a') as out:out.write('\n'+time.strftime('%Y-%m-%d %H:%M:%S')+' '+lines[0]+' Stop: '+finished['stop']+f'; {cpu/3600:.4f} recorded core-hours.\n')
print(lines[0])
